def stable_unique(items):
    if not items:
        return []

    result = []
    seen_hashable = set()
    seen_unhashable = []

    for item in items:
        try:
            h = hash(item)
        except TypeError:
            # 不可哈希元素（如 list、dict 或含它们的 tuple），用深比较去重
            is_dup = False
            for prev in seen_unhashable:
                if item == prev:
                    is_dup = True
                    break
            if not is_dup:
                seen_unhashable.append(item)
                result.append(item)
        else:
            # 可哈希元素：先查哈希集合
            if h in seen_hashable:
                continue
            # 防御性检查：可能与已记录的不可哈希元素相等（如 frozenset == set）
            is_dup = False
            for prev in seen_unhashable:
                if item == prev:
                    is_dup = True
                    break
            if not is_dup:
                seen_hashable.add(item)
                result.append(item)

    return result
