            invalid += 1
            continue
        if not is_number(status):
            invalid += 1
            continue

        stats = services.setdefault(service, {"latencies": [], "ok": 0})
        stats["latencies"].append(latency)
        if 200 <= status < 300:
            stats["ok"] += 1

    result = {"invalid": invalid}
