            idx = math.ceil(0.95 * n) - 1
            idx = max(0, min(idx, n - 1))
            p95 = latencies[idx]
        result[service] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95,
        }

    return result
