import heapq
from collections import defaultdict


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("Cycle detected: " + " -> ".join(cycle))
        self.cycle = cycle


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)

    for a, b in edges:
        if a not in node_set:
            raise ValueError(f"Unknown node in edges: {a!r}")
        if b not in node_set:
            raise ValueError(f"Unknown node in edges: {b!r}")

    adj = defaultdict(set)
    indeg = {n: 0 for n in nodes}
    seen = set()

    for a, b in edges:
        if (a, b) in seen:
            continue
        seen.add((a, b))
        if b not in adj[a]:
            adj[a].add(b)
            indeg[b] += 1

    heap = [n for n in indeg if indeg[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in sorted(adj[u]):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(indeg):
        remaining = set(indeg) - set(result)
        cycle = _find_cycle(remaining, adj)
        raise CycleError(cycle)

    return result


def _find_cycle(remaining, adj):
    start = min(remaining)
    path = [start]
    on_path = {start}
    stack = [(start, iter(sorted(v for v in adj[start] if v in remaining)))]

    while stack:
        u, it = stack[-1]
        advanced = False
        for v in it:
            if v in on_path:
                idx = path.index(v)
                return path[idx:] + [v]
            path.append(v)
            on_path.add(v)
            stack.append((v, iter(sorted(w for w in adj[v] if w in remaining))))
            advanced = True
            break
        if not advanced:
            stack.pop()
            path.pop()
            on_path.remove(u)

    return None
