import copy


def apply_patch_ops(document: dict, operations) -> dict:
    """
    对嵌套字典执行事务式更新。

    operations: (op, path, value) 三元组列表
        op: "set" | "delete" | "increment"
        path: 点分路径，如 "user.profile.age"
    任一步失败则抛出异常，不返回部分结果；成功返回新文档（深拷贝）。
    """
    new_doc = copy.deepcopy(document)

    def get_parent(doc, keys, create=False):
        """沿路径走到父级字典；create=True 时自动创建缺失的中间字典。"""
        current = doc
        for key in keys:
            if not isinstance(current, dict):
                raise TypeError(f"路径中间节点不是字典: key={key!r}")
            if key not in current:
                if create:
                    current[key] = {}
                else:
                    return None
            current = current[key]
        if not isinstance(current, dict):
            raise TypeError(f"路径父节点不是字典: path={'.'.join(keys)!r}")
        return current

    def apply_one(doc, op, path, value):
        if not isinstance(path, str) or not path:
            raise ValueError(f"非法路径: {path!r}")
        keys = path.split(".")

        if op == "set":
            parent = get_parent(doc, keys[:-1], create=True)
            parent[keys[-1]] = copy.deepcopy(value)

        elif op == "delete":
            parent = get_parent(doc, keys[:-1], create=False)
            if parent is None:
                return  # 父级不存在，视为路径不存在，不报错
            parent.pop(keys[-1], None)  # 键不存在也不报错

        elif op == "increment":
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(f"increment 的增量必须是 int/float: {value!r}")
            parent = get_parent(doc, keys[:-1], create=False)
            if parent is None or keys[-1] not in parent:
                raise KeyError(f"increment 目标路径不存在: {path!r}")
            current = parent[keys[-1]]
            if isinstance(current, bool) or not isinstance(current, (int, float)):
                raise TypeError(f"increment 目标值不是数值: path={path!r}, value={current!r}")
            parent[keys[-1]] = current + value

        else:
            raise ValueError(f"不支持的操作: {op!r}")

    # 事务式执行：先在副本上逐条应用，任何异常则整体失败（原文档从未被修改）
    for op, path, value in operations:
        apply_one(new_doc, op, path, value)

    return new_doc
