import time


class _Flight:
    __slots__ = ("event", "value", "error")

    def __init__(self):
        self.event = threading.Event()
        self.value = None
        self.error = None


class SingleFlightTTLCache:
    def __init__(self, ttl):
        self._ttl = ttl
        self._store = {}      # key -> (expire_time, value)
        self._flights = {}    # key -> _Flight
        self._lock = threading.Lock()

    def get(self, key, default=None):
        with self._lock:
            item = self._store.get(key)
            if item is None:
                return default
            expires, value = item
            if expires <= time.monotonic():
                del self._store[key]
                return default
            return value

    def set(self, key, value, ttl=None):
        expires = time.monotonic() + (self._ttl if ttl is None else ttl)
        with self._lock:
            self._store[key] = (expires, value)

    def delete(self, key):
        with self._lock:
            self._store.pop(key, None)

    def __len__(self):
        now = time.monotonic()
        with self._lock:
            expired = [k for k, (e, _) in self._store.items() if e <= now]
            for k in expired:
                del self._store[k]
            return len(self._store)

    def get_or_load(self, key, loader):
        while True:
            with self._lock:
                item = self._store.get(key)
                if item is not None:
                    expires, value = item
                    if expires > time.monotonic():
                        return value
                flight = self._flights.get(key)
                if flight is None:
                    flight = _Flight()
                    self._flights[key] = flight
                    is_leader = True
                else:
                    is_leader = False

            if is_leader:
                try:
                    value = loader()
                except BaseException as e:
                    with self._lock:
                        self._flights.pop(key, None)
                        flight.error = e
                        flight.event.set()
                    raise
                else:
                    self.set(key, value)
                    with self._lock:
                        self._flights.pop(key, None)
                        flight.value = value
                        flight.event.set()
                    return value
            else:
                # 等待者：只等待并共享 leader 的结果，绝不重复执行 loader
                flight.event.wait()
                if flight.error is not None:
                    raise flight.error
                return flight.value
