    if s[0] in ('-', '+'):
        raise ValueError("Sign not allowed in size string")

    pattern = r'(\d+(?:\.\d+)?)([KMG]?i?B)'
    match = re.fullmatch(pattern, s, re.IGNORECASE)

    if not match:
        raise ValueError(f"Invalid size string: {text!r}")

    num_str = match.group(1)
    unit = match.group(2).upper()

    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid number: {num_str!r}")

    units = {
        'B': 1,
        'KB': 1000,
        'KIB': 1024,
        'MB': 10**6,
        'MIB': 2**20,
        'GB': 10**9,
        'GIB': 2**30,
    }

    if unit not in units:
        raise ValueError(f"Unknown unit: {unit!r}")

    result = num * units[unit]
    return round(result)
