def _deep_equal(a, b):
    """Structural deep equality for arbitrary nested structures."""
    # Both dicts
    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False
        for key in a:
            try:
                if key not in b:
                    return False
            except TypeError:
                return False
            if not _deep_equal(a[key], b[key]):
                return False
        return True

    # Only one is a dict
    if isinstance(a, dict) or isinstance(b, dict):
        return False

    # Both are sequences (list or tuple)
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not _deep_equal(x, y):
                return False
        return True

    # Only one is a sequence
    if isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)):
        return False

    # Primitives
    try:
        return a == b
    except TypeError:
        return a is b


def stable_unique(items):
    """Return list with duplicates removed, preserving order of first occurrence."""
    if not items:
        return []

    result = []
    seen = []

    for item in items:
        is_duplicate = False
        for s in seen:
            if _deep_equal(item, s):
                is_duplicate = True
                break
        if not is_duplicate:
            result.append(item)
            seen.append(item)

    return result
