        if key not in counts:
            counts[key] = 0
            first_index[key] = i
            first_spelling[key] = w
        counts[key] += 1

    sorted_keys = sorted(
        counts.keys(),
        key=lambda key: (-counts[key], first_index[key])
    )

    return [(first_spelling[key], counts[key]) for key in sorted_keys[:k]]
