def merge_intervals(intervals):
    # Convert to list and validate
    interval_list = []
    for interval in intervals:
        if len(interval) != 2:
            raise ValueError("Each interval must have exactly 2 elements")
        start, end = interval
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) > end ({end})")
        interval_list.append((start, end))

    if not interval_list:
        return []

    # Sort by start
    interval_list.sort(key=lambda x: x[0])

    merged = [interval_list[0]]
    for current in interval_list[1:]:
        last_start, last_end = merged[-1]
        current_start, current_end = current
        if current_start <= last_end:
            # Merge
            merged[-1] = (last_start, max(last_end, current_end))
        else:
            merged.append(current)

    return merged
