            invalid_count += 1
            continue

        if service not in services:
            services[service] = {"latencies": [], "ok": 0, "count": 0}

        services[service]["latencies"].append(latency_ms)
        services[service]["count"] += 1
        if 200 <= status < 300:
            services[service]["ok"] += 1

    result = {"invalid": invalid_count}
    for service in sorted(services.keys()):
        data = services[service]
        n = data["count"]
        ok_rate = data["ok"] / n if n > 0 else 0.0
