from copy import deepcopy


def apply_patch_ops(document: dict, operations) -> dict:
    def _split_path(path):
        if not isinstance(path, str):
            raise TypeError("path must be a string")
        parts = path.split(".")
        if any(part == "" for part in parts):
            raise ValueError("path must not contain empty components")
        return parts

    def _is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    def _set_value(root, parts, value):
        node = root
        for part in parts[:-1]:
            if not isinstance(node, dict):
                raise TypeError("path traverses a non-dict value")
            if part not in node:
                node[part] = {}
            node = node[part]
        if not isinstance(node, dict):
            raise TypeError("path traverses a non-dict value")
        node[parts[-1]] = deepcopy(value)

    def _delete_value(root, parts):
        node = root
        for part in parts[:-1]:
            if not isinstance(node, dict) or part not in node:
                return
            node = node[part]
        if isinstance(node, dict) and parts[-1] in node:
            del node[parts[-1]]

    def _increment_value(root, parts, value):
        if not _is_number(value):
            raise TypeError("increment value must be int or float")
        node = root
        for part in parts[:-1]:
            if not isinstance(node, dict) or part not in node:
                raise KeyError("path not found")
            node = node[part]
        if not isinstance(node, dict) or parts[-1] not in node:
            raise KeyError("path not found")
        current = node[parts[-1]]
        if not _is_number(current):
            raise TypeError("increment path value must be numeric")
        node[parts[-1]] = current + value

    result = deepcopy(document)

    for op, path, value in operations:
        parts = _split_path(path)
        if op == "set":
            _set_value(result, parts, value)
        elif op == "delete":
            _delete_value(result, parts)
        elif op == "increment":
            _increment_value(result, parts, value)
        else:
            raise ValueError(f"unknown op: {op!r}")

    return result

def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    stats = {}
    for idx, word in enumerate(words):
        key = word.lower()
        if key not in stats:
            stats[key] = [word, 0, idx]
        stats[key][1] += 1

    ordered = sorted(stats.values(), key=lambda item: (-item[1], item[2]))
    return [(item[0], item[1]) for item in ordered[:k]]

