import heapq


class CycleError(Exception):
    def __init__(self, cycle: list[str]):
        self.cycle = cycle
        super().__init__(f"cycle detected: {cycle}")


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    nodes = list(nodes)
    edges = list(edges)
    node_set = set(nodes)

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError("edge references unknown node")

    adj: dict[str, list[str]] = {node: [] for node in node_set}
    indegree: dict[str, int] = {node: 0 for node in node_set}
    seen: set[tuple[str, str]] = set()

    for a, b in edges:
        if (a, b) in seen:
            continue
        seen.add((a, b))

        if a == b:
            raise CycleError([a, a])

        adj[a].append(b)
        indegree[b] += 1

    for successors in adj.values():
        successors.sort()

    heap = [node for node in indegree if indegree[node] == 0]
    heapq.heapify(heap)

    order: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)

        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) == len(node_set):
        return order

    remaining = set(node_set) - set(order)
    cycle = _find_cycle(adj, remaining)
    raise CycleError(cycle)


def _find_cycle(adj: dict[str, list[str]], nodes: set[str]) -> list[str]:
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in nodes}

    for start in sorted(nodes):
        if color[start] != WHITE:
            continue

        color[start] = GRAY
        path = [start]
        stack = [(start, iter(adj.get(start, [])))]

        while stack:
            current, it = stack[-1]
            descended = False

            for nxt in it:
                if nxt not in color:
                    continue

                if color[nxt] == GRAY:
                    idx = path.index(nxt)
                    return path[idx:] + [nxt]

                if color[nxt] == WHITE:
                    color[nxt] = GRAY
                    path.append(nxt)
                    stack.append((nxt, iter(adj.get(nxt, []))))
                    descended = True
                    break

            if not descended:
                stack.pop()
                path.pop()
                color[current] = BLACK

    return []

class _StreamingGroupSum:
    def __init__(self, rows):
        self._rows = rows
        self.invalid_count = 0
        self._order = None
        self._totals = None

    def __iter__(self):
        if self._order is None:
            self._consume()
        for key in self._order:
            yield key, self._totals[key]

    def _consume(self):
        order = []
        totals = {}
        invalid_count = 0

        for row in self._rows:
            try:
                _, key, value = row
            except (TypeError, ValueError):
                invalid_count += 1
                continue

            if isinstance(value, bool) or not isinstance(value, (int, float)):
                invalid_count += 1
                continue

            try:
                if key in totals:
                    totals[key] += value
                else:
                    totals[key] = value
                    order.append(key)
            except TypeError:
                invalid_count += 1
                continue

        self.invalid_count = invalid_count
        self._order = order
        self._totals = totals


