                parent = parent[part]
            parent[parts[-1]] = value

        elif op == "delete":
            parent = new_document
            reachable = True
            for part in parts[:-1]:
                if not isinstance(parent, dict) or part not in parent:
                    reachable = False
                    break
                parent = parent[part]

            if reachable and isinstance(parent, dict) and parts[-1] in parent:
                del parent[parts[-1]]

        elif op == "increment":
            if not _is_numeric(value):
                raise TypeError("increment value must be an int or float")

            parent = new_document
            for part in parts[:-1]:
                if not isinstance(parent, dict) or part not in parent:
                    raise KeyError(f"path '{path}' does not exist")
                parent = parent[part]

            if not isinstance(parent, dict) or parts[-1] not in parent:
                raise KeyError(f"path '{path}' does not exist")

            current = parent[parts[-1]]
            if not _is_numeric(current):
                raise TypeError(f"value at path '{path}' must be an int or float")

            parent[parts[-1]] = current + value

        else:
            raise ValueError(f"unsupported operation: {op!r}")

    return new_document

